    @staticmethod
    def _whole_window_row(
        root: Path, bundle_ids: list[str], *, adapter="stable", status="passed"
    ):
        # The helper can be evaluated before _extract_cells_corpus installs its
        # source manifest; make argument evaluation order irrelevant.
        if not (root / "campaign_manifests" / "synthetic-session.json").exists():
            install_synthetic_recovered_manifest(root, bundle_ids)
        descriptors = source_manifest_descriptors(
            root, [root / "campaign_manifests" / "synthetic-session.json"]
        )
        row = {
            "schema_version": WHOLE_WINDOW_SCHEMA,
            "record_type": "idle_admission_whole_window_verdict",
            "status": status,
            "campaign_policy": {"sha256": TEST_POLICY_SHA256},
            "bundle_ids": bundle_ids,
            "idle_admission_core": {
                "schema_version": IDLE_ADMISSION_CORE_SCHEMA,
                "policy_sha256": TEST_POLICY_SHA256,
                "members": [
                    {
                        "bundle_id": bundle_id,
                        "cpu_admission": {"decision": "admitted"},
                    }
                    for bundle_id in bundle_ids
                ],
                "adapter_wattage_continuity": {
                    "schema_version": ADAPTER_CONTINUITY_SCHEMA,
                    "decision": adapter,
                },
                "neg8_bracket": {
                    "schema_version": NEG8_BRACKET_SCHEMA,
                    "decision": "passed",
                    "policy": dict(REGISTERED_BRACKET_POLICY),
                },
                "conditions": [],
            },
        }
        row["row_provenance"] = build_row_provenance(
            policy_sha256=TEST_POLICY_SHA256,
            bundle_ids=bundle_ids,
            source_manifests=descriptors,
        )
        return row

    def _extract_cells_corpus(self, root: Path, *, whole_window_row=None) -> dict:
        bundle_ids = ["clean-a", "clean-b"]
        install_synthetic_recovered_manifest(root, bundle_ids)
        for index, bundle_id in enumerate(bundle_ids):
            # First/last members double as the NEG-8 references. The bracket
            # is evaluated over envelope CORNERS, so under the REGISTERED
            # 0.05 J tolerance the value spread (0.04) plus both envelope
            # half-widths (2 x 0.004) must stay within 0.05 — while the
            # nonzero spread keeps the floor statistics non-degenerate.
            write_bundle(
                root,
                bundle_id,
                make_summary(
                    40.0 + index * 0.04,
                    anchor_bound=0.004,
                ),
            )
        if whole_window_row is not None:
            (root / "campaign_log.jsonl").write_text(
                json.dumps(whole_window_row) + "\n", encoding="utf-8"
            )
        spec = {
            "schema_version": EXTRACTION_SPEC_SCHEMA_VERSION,
            "cells": [
                {
                    "cell_id": "whole-window-gate",
                    "kind": "absolute",
                    "metric": "gross_energy_j",
                    "window_class": "request",
                    "members": [
                        {"slot": bundle_id, "bundle_id": bundle_id}
                        for bundle_id in bundle_ids
                    ],
                }
            ],
        }
        return extract_cells(root, spec, strict_validator=lambda path, strict: [])

